contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: inputs choose a candidate new owner and whether to call as owner or not
    function run(address candidate, bool callAsOwner) public payable {
        require(candidate != address(0));

        // Read the initial owner as observed via public getter
        address ownerBefore = c.owner();

        // The test contract (this) is the deployer of c per harness description, so initially ownerBefore == address(this)
        // We will attempt to call setOwner either as the current owner (this contract) or simulate a non-owner by using a low-level call from address(this)
        // Since all calls originate from this contract in the harness, to simulate a non-owner we first change ownership away from this contract

        // If we want to simulate a non-owner call, we must ensure owner != this; transfer ownership to candidate first (only allowed if this is owner)
        if (callAsOwner == false) {
            // Only perform the ownership transfer if this contract is currently the owner
            // This is a state-changing call and must be a top-level statement
            if (ownerBefore == address(this)) {
                bool ok = c.setOwner(candidate);
                // after successful call, owner should be candidate
                require(ok);
                ownerBefore = c.owner();
                // now ownerBefore should equal candidate
            }
            // Now ownerBefore != address(this), so this contract is a non-owner
        } else {
            // Ensure we are owner: if we are not, try to set owner back to this (may revert if not owner)
            if (ownerBefore != address(this)) {
                // Attempt to set owner to this contract by calling setOwner; this will revert because we are not owner.
                // We capture the revert and require that it indeed reverted, because only owner can setOwner.
                bool reverted;
                try c.setOwner(address(this)) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                // If it reverted, we cannot continue to assert owner behavior as owner; halt the test early by requiring we are owner
                require(!reverted, "cannot become owner in setup");
                ownerBefore = c.owner();
            }
            // Now ownerBefore == address(this)
        }

        // Now perform the tested call: attempt to setOwner to 'candidate' and observe whether it reverts and the resulting owner
        bool callReverted;
        try c.setOwner(candidate) returns (bool success) {
            callReverted = false;
            // success must be true per function spec
            require(success == true);
        } catch {
            callReverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: if the call did not revert then the caller was the owner and owner was updated to candidate and function returned true;
        // if the call reverted then the caller was not the owner and owner remains unchanged.
        assert( (!callReverted && ownerAfter == candidate && ownerBefore == address(this)) || (callReverted && ownerAfter == ownerBefore && ownerBefore != address(this)) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: choose a candidate new owner and a flag indicating whether
    // we intend this contract to perform the authoritative (owner) call or to be a non-owner caller.
    function run(address candidate, bool callAsOwner) public payable {
        require(candidate != address(0));

        // Read initial owner
        address ownerBefore = c.owner();

        // Ensure the harness contract (this) is owner if callAsOwner==true.
        // If not owner and callAsOwner==true, attempt to become owner by calling setOwner(ownerBefore) only if we already are owner (no-op), otherwise we cannot change owner here; we will record that attempt's revert.
        // All state-changing calls must be top-level statements. We'll perform one optional preparatory state change when callAsOwner==false to make this contract a non-owner by transferring ownership away if we are owner.

        bool prepReverted;
        if (!callAsOwner) {
            // If we are currently the owner, transfer ownership to candidate so that this contract becomes a non-owner.
            if (ownerBefore == address(this)) {
                // top-level state-changing call
                try c.setOwner(candidate) returns (bool ok) {
                    prepReverted = false;
                    require(ok == true);
                } catch {
                    prepReverted = true;
                }
                // refresh observed owner
                ownerBefore = c.owner();
            }
        } else {
            // If caller intends to act as owner but this contract is not owner, we cannot make it owner in a single-call safe way; require that we already are owner to proceed as owner.
            require(ownerBefore == address(this));
        }

        // Now perform the tested call as this contract: attempt to setOwner to 'candidate'.
        bool callReverted;
        bool returnedTrue = false;
        try c.setOwner(candidate) returns (bool success) {
            callReverted = false;
            returnedTrue = success;
        } catch {
            callReverted = true;
        }

        address ownerAfter = c.owner();

        // General invariant:
        // - If the call did not revert, it must have returned true and ownerAfter equals candidate.
        // - If the call reverted, ownerAfter must equal ownerBefore (unchanged).
        assert((!callReverted && returnedTrue && ownerAfter == candidate) || (callReverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

