contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking a candidate newOwner and a boolean `asOwner`
    // If asOwner is true, the test will attempt to call setOwner from this contract (which is the owner because it deployed c).
    // If asOwner is false, the test will simulate a call from a different address by using a low-level call via address(c).
    // Because the checker invokes run exactly once and msg.sender for calls to c is this contract,
    // we instead model a non-owner call by calling setOwner via address(c).call with a fabricated sender is not possible in Solidity,
    // so we instead check the invariant using try/catch and the public owner getter: calls made by this contract should succeed,
    // and any attempted external call simulated by calling a view function cannot change owner. To create a meaningful non-owner revert test,
    // we rely on attempting to call setOwner when msg.sender != owner by first making owner a different address using setOwner from this contract,
    // then attempt setOwner again from this contract after changing owner away: that call must revert. The overall rule asserts that only the current owner can change owner.

    function run(address candidate, address other) public payable {
        require(candidate != address(0) && other != address(0));

        // Initially, this contract deployed c so owner == address(this)
        address ownerBefore = c.owner();

        // Ensure ownerBefore equals this contract
        // Now, as the current owner, set owner to `other` should succeed
        bool okSetToOther;
        try c.setOwner(other) returns (bool ok) { okSetToOther = ok; } catch { okSetToOther = false; }

        address ownerAfterSet = c.owner();

        // Now, this contract is not the owner anymore (owner == other). Attempting to set owner to candidate from this contract must revert.
        bool revertedWhenNotOwner;
        try c.setOwner(candidate) returns (bool ok) { revertedWhenNotOwner = false; } catch { revertedWhenNotOwner = true; }

        address ownerFinal = c.owner();

        // General rule: when the caller is the current owner the setOwner call succeeds and sets owner to the provided address;
        // and once ownership is transferred, a subsequent call by a non-owner (this contract) must revert and leave owner unchanged.
        assert(ownerBefore == address(this) && okSetToOther == true && ownerAfterSet == other && revertedWhenNotOwner == true && ownerFinal == other);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: take two distinct non-zero addresses
    function run(address newOwner, address candidate) public payable {
        require(newOwner != address(0) && candidate != address(0) && newOwner != candidate);

        // At deployment, this contract deployed c so c.owner() == address(this)
        address ownerBefore = c.owner();

        // As the current owner (this contract), transfer ownership to newOwner
        bool firstSucceeded;
        try c.setOwner(newOwner) returns (bool ok) { firstSucceeded = ok; } catch { firstSucceeded = false; }

        address ownerAfterFirst = c.owner();

        // Now this contract is no longer the owner if the transfer succeeded. Attempting to setOwner again from this contract
        // to change owner to `candidate` must revert (i.e., fail) and leave owner unchanged.
        bool revertedSecond;
        try c.setOwner(candidate) returns (bool ok2) { revertedSecond = false; } catch { revertedSecond = true; }

        address ownerAfterSecond = c.owner();

        // General rule: the initial transfer by the real owner succeeds and sets owner to newOwner,
        // and after that, this contract (no longer owner) cannot change owner: the second call must revert and owner remains newOwner.
        assert(ownerBefore == address(this) && firstSucceeded == true && ownerAfterFirst == newOwner && revertedSecond == true && ownerAfterSecond == newOwner);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: take one address to set as new owner
    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // Read owner before any action; at deployment this contract was the owner
        address ownerBefore = c.owner();

        // Attempt to call setOwner as the current owner (this contract)
        bool succeeded;
        try c.setOwner(newOwner) returns (bool ok) { succeeded = ok; } catch { succeeded = false; }
        address ownerAfter = c.owner();

        // Now attempt to call setOwner again from this contract to a different address to observe non-owner behavior
        address another = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, ownerBefore)))));
        // ensure another is non-zero and different
        if (another == address(0) || another == newOwner) {
            another = address(1);
        }

        bool revertedWhenNonOwner;
        // This second call is made by this contract; if the first call succeeded and changed owner, this contract is no longer owner
        try c.setOwner(another) returns (bool ok2) { revertedWhenNonOwner = false; } catch { revertedWhenNonOwner = true; }
        address ownerAfterSecond = c.owner();

        // General rule:
        // - If the first call returned true (succeeded == true) then ownerAfter == newOwner.
        // - If the first call returned false (i.e., it reverted) then ownerAfter == ownerBefore.
        // - If the first call succeeded and thus this contract ceased to be owner, the subsequent attempt from this contract must revert and leave owner unchanged.
        assert(
            (succeeded && ownerAfter == newOwner && revertedWhenNonOwner && ownerAfterSecond == newOwner)
            || (!succeeded && ownerAfter == ownerBefore && ownerAfterSecond == ownerBefore)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: try calling setOwner with an arbitrary address
    function run(address candidate) public payable {
        require(candidate != address(0));

        // read owner before the call
        address ownerBefore = c.owner();

        // attempt to call setOwner from this contract (msg.sender == address(this) for calls to c)
        bool reverted;
        bool returnedFalse = false;
        try c.setOwner(candidate) returns (bool ok) { reverted = false; returnedFalse = !ok; } catch { reverted = true; }

        // read owner after the call
        address ownerAfter = c.owner();

        // General rule: If the call did not revert then it must have returned true and ownerAfter == candidate.
        // If the call reverted then ownerAfter == ownerBefore. This enforces that only the true owner (address(this) when deployed) can change owner.
        assert((!reverted && !returnedFalse && ownerAfter == candidate) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: candidate new owner and a flag whether to attempt the call
    function run(address newOwner, bool doCall) public payable {
        require(true);

        // read owner before any action
        address ownerBefore = c.owner();

        bool didRevert = false;
        bool ret = false;

        if (doCall) {
            // perform the potentially-reverting call and capture whether it reverted and its return value
            try c.setOwner(newOwner) returns (bool ok) {
                didRevert = false;
                ret = ok;
            } catch {
                didRevert = true;
                ret = false;
            }
        }

        // read owner after
        address ownerAfter = c.owner();

        // General rule:
        // - If the call reverted (or was not performed), ownerAfter is either unchanged (ownerBefore) or equals newOwner only if the call succeeded.
        // - If the call did not revert, then ret must be true and ownerAfter equals newOwner.
        // - If the call reverted (or wasn't performed), ownerAfter equals ownerBefore.
        // We express this as: if doCall and not reverted then ret==true and ownerAfter==newOwner; otherwise ownerAfter==ownerBefore.
        assert((doCall && !didRevert) ? (ret == true && ownerAfter == newOwner) : (ownerAfter == ownerBefore));
    }

    receive() external payable { }
}
